layer.css:
@import url("https://fonts.googleapis.com/css2?family=Roboto:ital,wght@0,100..900;1,100..900&display=swap");
[data-ryt="pitch"] { color: var(--ryt-text); border-radius: 0px; font-family: system-ui, -apple-system, "Segoe UI", Roboto, "Helvetica Neue", "Noto Sans", "Liberation Sans", Arial, sans-serif, "Apple Color Emoji", "Segoe UI Emoji", "Segoe UI Symbol", "Noto Color Emoji"; font-size: 16px; font-weight: 400; font-style: normal; line-height: 1.5; letter-spacing: normal; text-transform: none; text-decoration-style: solid; text-decoration-color: var(--ryt-text); text-decoration-thickness: auto; text-underline-offset: auto; padding-top: 0px; padding-right: 0px; padding-bottom: 0px; padding-left: 0px; transition: all }
article[data-ryt="rec-card"] { background-color: var(--ryt-bg); border-top: 1px solid color-mix(in srgb, var(--ryt-border) 14%, transparent); border-right: 1px solid color-mix(in srgb, var(--ryt-border) 14%, transparent); border-bottom: 1px solid color-mix(in srgb, var(--ryt-border) 14%, transparent); border-left: 1px solid color-mix(in srgb, var(--ryt-border) 14%, transparent); border-radius: 12px; box-shadow: rgba(9, 30, 43, 0.06) 0px 1px 2px 0px, rgba(9, 30, 43, 0.4) 0px 14px 30px -20px; transition: transform 0.25s, box-shadow 0.25s, border-color 0.25s }
[data-ryt="footer"] { color: var(--ryt-text); font-style: normal; letter-spacing: normal; text-transform: none }
[data-ryt="credit"] a, [data-ryt="review"] a, [data-ryt="bio"] a { color: var(--ryt-border); border-radius: 0px; font-weight: 400; font-style: normal; letter-spacing: normal; text-transform: none; text-decoration-style: solid; text-decoration-color: var(--ryt-border); text-decoration-thickness: auto; text-underline-offset: auto; transition: all }
[data-ryt="hero"] h1 { color: #909294; font-family: system-ui, -apple-system, "Segoe UI", Roboto, "Helvetica Neue", "Noto Sans", "Liberation Sans", Arial, sans-serif, "Apple Color Emoji", "Segoe UI Emoji", "Segoe UI Symbol", "Noto Color Emoji"; font-size: 40px; font-weight: 500; font-style: normal; line-height: 1.2; letter-spacing: normal; text-transform: none; text-decoration-style: solid; text-decoration-color: var(--ryt-bg); text-decoration-thickness: auto; text-underline-offset: auto; text-shadow: rgba(0, 0, 0, 0.55) 0px 1px 2px, rgba(0, 0, 0, 0.45) 0px 10px 30px; transition: all }
[data-ryt="section"] > h2 { color: #909294; border-radius: 0px; font-family: system-ui, -apple-system, "Segoe UI", Roboto, "Helvetica Neue", "Noto Sans", "Liberation Sans", Arial, sans-serif, "Apple Color Emoji", "Segoe UI Emoji", "Segoe UI Symbol", "Noto Color Emoji"; font-weight: 500; font-style: normal; line-height: 1.2; letter-spacing: normal; text-transform: none; text-decoration-style: solid; text-decoration-color: var(--ryt-bg); text-decoration-thickness: auto; text-underline-offset: auto; text-shadow: rgba(0, 0, 0, 0.55) 0px 1px 2px, rgba(0, 0, 0, 0.45) 0px 10px 30px; transition: all }
[data-ryt="button"] { color: var(--ryt-bg); background-color: var(--ryt-border); border-top: 1px solid rgba(0, 0, 0, 0); border-right: 1px solid rgba(0, 0, 0, 0); border-bottom: 1px solid rgba(0, 0, 0, 0); border-left: 1px solid rgba(0, 0, 0, 0); border-radius: 6.4px; font-family: system-ui, -apple-system, "Segoe UI", Roboto, "Helvetica Neue", "Noto Sans", "Liberation Sans", Arial, sans-serif, "Apple Color Emoji", "Segoe UI Emoji", "Segoe UI Symbol", "Noto Color Emoji"; font-weight: 600; font-style: normal; line-height: 1.5; letter-spacing: normal; text-transform: none; text-decoration-style: solid; text-decoration-color: var(--ryt-bg); text-decoration-thickness: auto; text-underline-offset: auto; padding-top: 9.92px; padding-right: 18.4px; padding-bottom: 9.92px; padding-left: 18.4px; transition: color 0.15s ease-in-out, background-color 0.15s ease-in-out, border-color 0.15s ease-in-out, box-shadow 0.15s ease-in-out }
[data-ryt="cover"] { border-radius: 0px }
[data-ryt="rec-card"] [data-ryt="title"] a { color: var(--ryt-border); border-radius: 0px; font-family: system-ui, -apple-system, "Segoe UI", Roboto, "Helvetica Neue", "Noto Sans", "Liberation Sans", Arial, sans-serif, "Apple Color Emoji", "Segoe UI Emoji", "Segoe UI Symbol", "Noto Color Emoji"; font-weight: 500; font-style: normal; letter-spacing: normal; text-transform: none; text-decoration-style: solid; text-decoration-color: var(--ryt-border); text-decoration-thickness: auto; text-underline-offset: auto; transition: all }
[data-ryt="brand"] { color: #909294; border-radius: 0px; font-family: system-ui, -apple-system, "Segoe UI", Roboto, "Helvetica Neue", "Noto Sans", "Liberation Sans", Arial, sans-serif, "Apple Color Emoji", "Segoe UI Emoji", "Segoe UI Symbol", "Noto Color Emoji"; font-size: 20.8px; font-weight: 600; font-style: normal; line-height: 1.1; letter-spacing: 0.208px; text-transform: none; text-decoration-style: solid; text-decoration-color: var(--ryt-bg); text-decoration-thickness: auto; text-underline-offset: auto; text-shadow: rgba(0, 0, 0, 0.35) 1px 1px 2px; transition: color 0.3s, border-top 0.3s }
[data-ryt="nav"] a { color: #909294; border-radius: 0px; font-family: system-ui, -apple-system, "Segoe UI", Roboto, "Helvetica Neue", "Noto Sans", "Liberation Sans", Arial, sans-serif, "Apple Color Emoji", "Segoe UI Emoji", "Segoe UI Symbol", "Noto Color Emoji"; font-size: 16px; font-weight: 400; font-style: normal; line-height: 1.5; letter-spacing: normal; text-transform: none; text-decoration-style: solid; text-decoration-color: var(--ryt-bg); text-decoration-thickness: auto; text-underline-offset: auto; text-shadow: rgba(0, 0, 0, 0.35) 1px 1px 2px; padding-top: 11.2px; padding-right: 8px; padding-bottom: 11.2px; padding-left: 8px; transition: color 0.3s, border-top 0.3s }
[data-ryt="rec-card"] [data-ryt="title"] { color: var(--ryt-border); border-radius: 0px; font-family: system-ui, -apple-system, "Segoe UI", Roboto, "Helvetica Neue", "Noto Sans", "Liberation Sans", Arial, sans-serif, "Apple Color Emoji", "Segoe UI Emoji", "Segoe UI Symbol", "Noto Color Emoji"; font-size: 23.2px; font-weight: 500; font-style: normal; line-height: 1.2; letter-spacing: normal; text-transform: none; text-decoration-style: solid; text-decoration-color: var(--ryt-border); text-decoration-thickness: auto; text-underline-offset: auto; transition: all }
[data-ryt="nav"] a:hover { color: rgba(0,0,0, 0.8); text-shadow: rgba(0, 0, 0, 0.2) 2px 2px 2px; text-shadow: rgba(0, 0, 0, 0.2) 2px 2px 2px; text-decoration-line: underline; text-decoration-style: initial; text-decoration-color: initial; text-decoration-thickness: 2px; text-underline-offset: 0.55em }
[data-ryt="brand"]:hover { color: rgba(0,0,0, 1); text-shadow: rgba(0, 0, 0, 0.2) 2px 2px 2px }
[data-ryt="rec-card"] [data-ryt="title"] a:hover { text-decoration-line: underline; text-decoration-thickness: initial; text-decoration-style: initial; text-decoration-color: initial; text-underline-offset: 0.18em }
[data-ryt="cover"]:hover { transform: scale(1.04) }
[data-ryt="button"]:hover { color: initial; background-color: initial; background-image: initial; background-color: rgb(2, 74, 113); color: var(--ryt-bg) }
article[data-ryt="rec-card"]:hover { border-top-color: color-mix(in srgb, var(--ryt-border) 32%, transparent); border-right-color: color-mix(in srgb, var(--ryt-border) 32%, transparent); border-bottom-color: color-mix(in srgb, var(--ryt-border) 32%, transparent); border-left-color: color-mix(in srgb, var(--ryt-border) 32%, transparent); box-shadow: rgba(9, 30, 43, 0.07) 0px 2px 4px, rgba(9, 30, 43, 0.5) 0px 24px 42px -24px; transform: translateY(-2px) }
